def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_D = 0
    my_D = 0
    for a, b in history:
        if b == 'D':
            opp_D += 1
        if a == 'D':
            my_D += 1

    if opp_D > 0:
        if opp_D * 2 > n:
            return 'D'
        last_my, last_opp = history[-1]
        my_def_last2 = (last_my == 'D')
        if not my_def_last2 and n >= 2:
            my_def_last2 = (history[-2][0] == 'D')
        if n >= 3:
            opp_def_last3 = 0
            for i in range(n - 3, n):
                if history[i][1] == 'D':
                    opp_def_last3 += 1
        else:
            opp_def_last3 = opp_D
        if last_opp == 'D':
            if opp_def_last3 >= 3:
                return 'D'
            if my_def_last2:
                return 'C'
            return 'D'
        else:
            if last_my == 'D':
                return 'C'
            return 'C'
    else:
        if my_D == 0:
            if n >= 9:
                return 'D'
            return 'C'
        else:
            last_my_def_idx = -1
            for i in range(n - 1, -1, -1):
                if history[i][0] == 'D':
                    last_my_def_idx = i
                    break
            if last_my_def_idx != -1 and n - last_my_def_idx >= 10:
                return 'D'
            return 'C'
